# ❌ OLD: Writing custom method names prevents using standard Python features
# like len(deck), for card in deck, deck[0], or random.choice(deck).
class DeckLegacy:
  def __init__(self):
    self._cards = ['A', 'K', 'Q', 'J']

  def getLength(self):
    return len(self._cards)

  def getItem(self, index):
    return self._cards[index]

# Cannot do: len(deck) -> TypeError
