import random

class DeckModern:
  def __init__(self):
    self._cards = ['A', 'K', 'Q', 'J', '10', '9']

  # ✅ Enables: len(deck)
  def __len__(self):
    return len(self._cards)

  # ✅ Enables: deck[0], deck[1:3], for card in deck, 'A' in deck!
  def __getitem__(self, position):
    return self._cards[position]

deck = DeckModern()
print(len(deck)) # 6
print(deck[0]) # 'A'
print(random.choice(deck)) # Works out of the box with standard library!
